import{_ as a,o as t,c as r,a8 as s}from"./chunks/framework.CNIpabDg.js";const m=JSON.parse('{"title":"Component map","description":"Find the runtime owner, reusable contract, driver or executable responsible for a Xila capability.","frontmatter":{"layout":"doc","docType":"explanation","description":"Find the runtime owner, reusable contract, driver or executable responsible for a Xila capability."},"headers":[],"relativePath":"explanation/architecture/components.md","filePath":"explanation/architecture/components.md","lastUpdated":1793145952000}'),n={name:"explanation/architecture/components.md"};function i(o,e,l,c,h,u){return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[...e[0]||(e[0]=[s('<h1 id="component-map" tabindex="-1">Component map <a class="header-anchor" href="#component-map" aria-label="Permalink to &quot;Component map&quot;">​</a></h1><p>The Xila codebase separates four <strong>roles</strong> across Core, Applications and Platforms: <a href="/explanation/architecture/subsystems/">subsystems</a>, <a href="/explanation/architecture/libraries/">libraries</a>, <a href="/explanation/architecture/drivers/">drivers</a> and <a href="/explanation/architecture/executables/">executables</a>. All are Rust crates; a Rust module is a language construct, not a separate architectural category.</p><h2 id="where-does-a-component-belong" tabindex="-1">Where does a component belong? <a class="header-anchor" href="#where-does-a-component-belong" aria-label="Permalink to &quot;Where does a component belong?&quot;">​</a></h2><ul><li><strong>Subsystem:</strong> owns or coordinates an installed runtime capability with a lifecycle in the assembled Xila instance. The <a href="/explanation/architecture/subsystems/virtual_file_system.html">VFS</a> owns the mounted namespace; <a href="/explanation/architecture/subsystems/graphics.html">graphics</a> coordinates LVGL and input state.</li><li><strong>Library:</strong> defines reusable contracts, helpers or implementations that do not need a separate installation/lifecycle. <a href="/explanation/architecture/libraries/file_system.html">File system</a> defines storage contracts; <a href="/explanation/architecture/libraries/little_fs.html">LittleFS</a> implements them.</li><li><strong>Driver:</strong> adapts a generic capability to a particular platform, as in the <a href="/explanation/architecture/drivers/wasm.html">browser driver</a> or <a href="/explanation/architecture/drivers/native.html">native driver</a>.</li><li><strong>Executable:</strong> consumes the assembled services as a program, launcher or guest runtime. The <a href="/explanation/architecture/executables/wasm.html">WASM executable</a> owns <a href="/explanation/architecture/executables/wasm.html">Wasmi execution within WASM</a> and <a href="/explanation/architecture/executables/bindings.html">guest/host bindings</a>.</li></ul><p>Core retains portable subsystem and library crates, Applications owns official executables and Wasmi, and Platforms owns the concrete drivers and final runtime assembly. See the <a href="/explanation/architecture/">repository architecture</a> for those boundaries.</p><p>Internal mutable state alone is not evidence of a subsystem: the key is <strong>runtime ownership and assembly</strong>. Some reusable executable helpers depend on subsystem interfaces without themselves becoming runtime services.</p><h2 id="follow-a-request" tabindex="-1">Follow a request <a class="header-anchor" href="#follow-a-request" aria-label="Permalink to &quot;Follow a request&quot;">​</a></h2><p>A file request starts in an <a href="/explanation/architecture/executables/">executable</a>, reaches the <a href="/explanation/architecture/subsystems/virtual_file_system.html">VFS</a>, uses <a href="/explanation/architecture/libraries/file_system.html">file-system contracts</a>, then dispatches to a mounted <a href="/explanation/architecture/libraries/little_fs.html">LittleFS</a> instance or device driver.</p><p>A WebAssembly guest uses the <a href="/explanation/architecture/executables/wasm.html">WASM runtime and bindings</a> owned by the WASM executable. Those adapters pass operations to the same task/VFS/time/graphics subsystem managers used by native executables.</p><p>See the <a href="/explanation/architecture/">architecture overview</a> for lifecycle, dependency and process-global integration details.</p>',10)])])}const d=a(n,[["render",i]]);export{m as __pageData,d as default};
